import 'package:flet/flet.dart';
import 'package:flutter/widgets.dart';
import 'package:mobile_scanner/mobile_scanner.dart';

class BarcodeScannerControl extends StatefulWidget {
  final Control? parent;
  final Control control;
  final FletControlBackend backend;

  const BarcodeScannerControl(
      {super.key,
      required this.parent,
      required this.control,
      required this.backend});

  @override
  State<BarcodeScannerControl> createState() => _BarcodeScannerControlState();
}

class _BarcodeScannerControlState extends State<BarcodeScannerControl>
    with FletStoreMixin {
  MobileScannerController? _controller;
  bool _handled = false;

  @override
  void initState() {
    debugPrint("BarcodeScanner.initState($hashCode)");
    widget.control.onRemove.clear();
    widget.control.onRemove.add(_onRemove);
    super.initState();
  }

  void _onRemove() {
    debugPrint("BarcodeScanner.remove($hashCode)");
    _controller?.dispose();
    _controller = null;
    widget.backend.unsubscribeMethods(widget.control.id);
  }

  Future<String> _start() async {
    await _controller?.dispose();
    _handled = false;
    final controller = MobileScannerController();
    if (!mounted) {
      await controller.dispose();
      return "false";
    }
    setState(() {
      _controller = controller;
    });
    return "true";
  }

  Future<void> _stop() async {
    final controller = _controller;
    _controller = null;
    if (mounted) {
      setState(() {});
    }
    await controller?.dispose();
  }

  void _onDetect(BarcodeCapture capture) {
    if (_handled || capture.barcodes.isEmpty) {
      return;
    }
    final code = capture.barcodes.first.rawValue;
    if (code == null || code.isEmpty) {
      return;
    }
    _handled = true;
    widget.backend.triggerControlEvent(widget.control.id, "detect", code);
    // Release the hardware as soon as a code is found -- matches the old
    // CameraEngine.stream_views' "stop on first hit" timing. The preview
    // goes blank rather than freezing on the last frame (mobile_scanner has
    // no freeze-frame API); scheduled after the current callback returns so
    // disposing the controller doesn't happen mid frame-processing.
    Future.microtask(_stop);
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BarcodeScanner build: ${widget.control.id}");

    () async {
      widget.backend.subscribeMethods(widget.control.id,
          (methodName, args) async {
        switch (methodName) {
          case "start":
            return await _start();
          case "stop":
            await _stop();
            return "true";
        }
        return null;
      });
    }();

    final controller = _controller;
    if (controller == null) {
      return const SizedBox.shrink();
    }
    return MobileScanner(controller: controller, onDetect: _onDetect);
  }
}
